function varargout = staltastack(ddir, evs_str, station, location, sta, ...
    lta, colo, cohi)
% STALTASTACK(ddir, evs_str, tstation, [stlo stla], sta, lta, colo, cohi)
% [rstack, distcount, t, evs_used] = STALTASTACK(...)
%
% Stacks STA/LTA ratios the waveforms recorded at T-wave station. Then plot
% the stacked result.
%
% INPUT:
% ddir          directory to the sacfiles generated by QUERYSOT
% evs_str       event structs containing the following variables
%   - PreferredTime
%   - PreferredLatitude
%   - PreferredLongitude
%   - PreferredDepth
%   - PreferredMagnitudeValue
%   - PreferredMagnitudeType
%   - PublicId
%   - tT
% tstation              network.station.location.channel for T-wave
% [stlo stla]           lon,lat cooridnates of tstation
% sta           short-term average window length
% lta           long-term average window length
% colo          low corner frequency for bandpass filtering
% cohi          high corner frequency for bandpass filtering
%
% OUTPUT:
% rstack        stacked STA/LTA timeseries with epicentral distance bins
% distcount     values for each epicentral distance bin
% t             time
% evs_used      events actually used for STA/LTA stacking
%
% SEE ALSO:
% QUERYSTACK, READQUERYSTACK, QUERYSTACK_ROUTINE
%
% Last modified by spipatprathanporn@ucsd.edu, 10/12/2026


N = length(evs_str.PreferredTime);

% output format from instrument response remove function
resp_output_fmt = 'velocity';

% compute the origin datetime
evs_str.dt_origin = datetime(evs_str.PreferredTime, 'TimeZone', 'UTC', ...
    'Format', 'uuuu-MM-dd''T''HH:mm:ss.SSSSSS');

%% read seismograms and stack stalta
distcount = zeros(1,200);
rstack = zeros([144001 length(distcount)]);
ii_used = false(N,1);

for ii = 1:N
    try
        % read local station seismograms for event ii
        dt_origin = evs_str.dt_origin(ii);
        dt_begin = dt_origin - minutes(1);
        dt_end = dt_origin + minutes(121);
        fname = sprintf('%s.%s_%s.sac', station, dt_begin, dt_end);
        fname = replace(fname, '.000000', '');
        fname = fullfile(ddir, fname);
        
        try
            [seis, hdr] = readsac(fname);
        catch ME
            % sometimes stations switch from BHN,BHE to BH1,BH2 or
            % vice-versa
            fprintf('File %s does not exist in %s or it cannot be read.\n', ...
                fname, ddir);
            if contains(fname, 'BH1')
                fprintf('Try reading channel BHN instead of BH1 ...\n')
                fname = replace(fname, 'BH1', 'BHN');
            elseif contains(fname, 'BH2')
                fprintf('Try reading channel BHE instead of BH2 ...\n')
                fname = replace(fname, 'BH2', 'BHE');
            elseif contains(fname, 'BHN')
                fprintf('Try reading channel BH1 instead of BHN ...\n')
                fname = replace(fname, 'BHN', 'BH1');
            elseif contains(fname, 'BHE')
                fprintf('Try reading channel BH2 instead of BHE ...\n')
                fname = replace(fname, 'BHE', 'BH2');
            else
                ME.getReport()
                fprintf("Don't know how to handle. Move on.\n")
                continue
            end
            [seis, hdr] = readsac(fname);
        end

        [~, ~, ~, fs, ~, dts, ~] = gethdrinfo(hdr);
        t = seconds(dts - dt_origin);
        
        % remove instrument response
        sacpzfile = [fname 'pz'];
        seis = detrend(seis, 2) .* shanning(length(seis), 0.003);
        seis = real(transfer(seis, 1/fs, [0.01 0.02 8 10], ...
            resp_output_fmt, sacpzfile, 'sacpz'));

        % downsample to 20 Hz if the sampling rate is 40 Hz
        if abs(fs - 40) < 0.001
            seis = lowpass(seis, fs, 10, 2, 2, 'butter', 'linear');
            t = downsample(t, 2);
            seis = downsample(seis, 2);
            fs = fs/2;
            hdr.DELTA = hdr.DELTA * 2;
            hdr.NPTS = length(seis);
            hdr.E = hdr.B + (hdr.NPTS-1) * hdr.DELTA;
        end

        % resampling to align the samples
        tim = (-30:1/20:7200)';
        seis = interp1(t, seis, tim);
        fs = 20;
    
        % apply a bandpass filter
        seis = bandpass(seis, fs, colo, cohi, 2, 2, 'butter', 'linear');

        % compute stalta
        [~,~,~,ratio,tim1] = stalta(seis, 1/fs, [tim(1) tim(end)], sta, lta);
    
        % resampling to align the samples
        wh = and(tim1>=0, tim1<=7200);
        t = tim1(wh);
        ratio = ratio(wh);

        % stacking
        if ~isempty(t) && ~isempty(ratio) && max(ratio) > 1
            whbin = ceil(2*evs_str.distdeg(ii));
            ratio(isnan(ratio)) = 0;
            rstack(:,whbin) = rstack(:,whbin) + ratio;
            distcount(whbin) = distcount(whbin) + 1;
            [evs_str.ratio_max(ii), imax] = max(ratio);
            evs_str.t_ratio_max(ii) = t(imax);
            ii_used(ii) = true;
        else
            evs_str.ratio_max(ii) = nan;
            evs_str.t_ratio_max(ii) = nan;
        end
    catch ME
        ME.getReport()
        evs_str.ratio_max(ii) = nan;
        evs_str.t_ratio_max(ii) = nan;
    end
end

%% stack the stalta

% for ii = 1:N
%     if ~isempty(tr(ii).t) && ~isempty(tr(ii).ratio) && ...
%             max(tr(ii).ratio) > 1
%         try
%             whbin = ceil(2*evs_str.distdeg(ii));
%             tr(ii).ratio(isnan(tr(ii).ratio)) = 0;
%             rstack(:,whbin) = rstack(:,whbin) + tr(ii).ratio;
%             distcount(whbin) = distcount(whbin) + 1;
%             [evs_str.ratio_max(ii), imax] = max(tr(ii).ratio);
%             evs_str.t_ratio_max(ii) = tr(ii).t(imax);
%             ii_used(ii) = true;
%         catch ME
%             ME.getReport()
%             evs_str.ratio_max(ii) = nan;
%             evs_str.t_ratio_max(ii) = nan;
%             keyboard
%         end
%     else
%         evs_str.ratio_max(ii) = nan;
%         evs_str.t_ratio_max(ii) = nan;
%     end
% end
rstack = rstack ./ distcount;

fn = fieldnames(evs_str);
for ii = 1:length(fn)
    evs_used.(fn{ii}) = evs_str.(fn{ii})(ii_used);
end

wht = and(abs(evs_used.t_ratio_max-evs_used.distkm/1.5) <= 200, ...
    evs_used.ratio_max >= 3);

%% plot the STA/LTA stack
figure(1)
set(gcf, 'Units', 'inches', 'Position', [0 1 6 8])
im = imagesc([0 100], [0 7200], rstack);
set(im, 'AlphaData', ~isnan(rstack))
axis xy
axis tight
grid on
cbase = [1 1 1; 1 0.8 0.3; 1 0 0; 1 0 1; 0.5 0 1; 0.2 0.8 1];
colormap(interp1(linspace(0,255,6), cbase, 0:255))
clim([0.9 1.4])
xticks(0:10:100)
yticks(0:600:7200)
xlabel('range (degrees)')
ylabel('time (s)')
title(sprintf('%s | %.1f-%.1f Hz | STA: %d, LTA: %d', station, colo, ...
    cohi, sta, lta))
cb = colorbar;
set(cb, 'TickDirection', 'out')
set(get(cb, 'Label'), 'String', 'STA/LTA ratio')
set(gca, 'TickDir', 'out', 'Box', 'on', 'FontSize', 11)
set(gcf, 'Renderer', 'painters')
figdisp(sprintf('%s_%s_%d_%d.eps', mfilename, station, sta, lta), [], [], ...
    2, [], 'epstopdf')

figure(2)
set(gcf, 'Units', 'inches', 'Position', [0 1 8 7])
ax = polarbasemap2(gca, 100, location(1), location(2), false);
delete(ax.Children(end));
plotpolarmap2(@scatter, gca, evs_used.PreferredLongitude(wht), ...
    evs_used.PreferredLatitude(wht), 12, evs_used.ratio_max(wht), ...
    'filled', 'MarkerEdgeColor', 'k');
plotpolarmap2(@scatter, gca, location(1), location(2), 40, [1 0.5 0.2], ...
    'filled', '^', 'MarkerEdgeColor','k');
title(sprintf('%d/%d events with STA/LTA ratio >= 3', sum(wht), ...
    sum(ii_used)))
colormap(kelicol);
clim([1 6])
cb = colorbar;
set(cb, 'TickDirection', 'out', 'FontSize', 11)
set(get(cb, 'Label'), 'String', 'STA/LTA ratio')
set(gca, 'TickDir', 'out', 'Box', 'on', 'FontSize', 11)
set(gcf, 'Renderer', 'painters')
figdisp(sprintf('%s_%s_observable_T-phase.eps', mfilename, station), ...
    [], [], 2, [], 'epstopdf')

figure(3)
set(gcf, 'Units', 'inches', 'Position', [0 1 9 4.2])
N = histcounts2(mod(evs_used.PreferredLongitude(wht), ...
    360), evs_used.PreferredLatitude(wht), 0:10:360, -90:10:90);
im = imagesc([5 355], [-85 85], log10(N') .* (log10(N')./log10(N')));
set(im, 'AlphaData', ~isnan(get(im, 'CData')))
hold on
scatter(mod(location(1),360), location(2), 40, [1 0.5 0.2], 'filled', ...
    '^', 'MarkerEdgeColor','k');
grid on
xticks(0:30:360)
yticks(-90:30:90)
axis tight
axis equal
axis xy
plotcont;
h = plotplates;
set(h, 'Color', 'r', 'LineWidth', 1)
cb = colorbar;
cbticklabels = round(10 .^ get(cb, 'Ticks'));
colormap(jet(2*(length(cbticklabels)-1)))
set(cb, 'TickDirection', 'out', 'Ticks', log10(cbticklabels), ...
    'TickLabels', cbticklabels, 'FontSize', 11)
set(get(cb, 'Label'), 'String', 'Event counts in 10x10 degrees')
xlabel('longitude (degrees)')
ylabel('latitude (degrees)')
title(sprintf('M5.0+ | %s | 2000-2025 | STA/LTA >= 3 | %d events', ...
    cindeks(split(station, '.00'), 1), sum(wht)))
set(gca, 'TickDir', 'out', 'FontSize', 11, 'Box', 'on')
set(gcf, 'Renderer', 'painters')
exportgraphics(gcf, fullfile(getenv('EPS'), ...
    sprintf('%s_%s_observable_T-phase_density.pdf', mfilename, ...
    station)), 'ContentType', 'image', 'Resolution', 600, 'Padding', 0);

%% Collect the output
outputs = {rstack, distcount, t, evs_used};
varargout = outputs(1:nargout);
end